package org.jlinalg.cli;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.embedding.SimplePptMath;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Compare complete original data-only CPU families; no Python execution or object deserialization. */
public final class SimplePptMathMatrix {
    private SimplePptMathMatrix() { }
    static long numeric,nonfinite,cases;
    static final SimplePptMath.Limits LIMITS=SimplePptMath.Limits.defaults();
    static final List<Map<String,Object>> diagnosticComparisons=new ArrayList<>();
    record Vector(List<Integer> shape,String dtype,ByteBuffer data,int length) {
        double get(int at)throws IOException {require(at>=0&&at<length,"Array index outside complete shape");return switch(dtype){case "<f8"->data.getDouble(at*8);case "<i8"->data.getLong(at*8);case "<i4"->data.getInt(at*4);case "|u1"->Byte.toUnsignedInt(data.get(at));default->throw new IOException("Unsupported original primitive dtype: "+dtype);};}
    }
    static Map<String,Object> read(Path path)throws IOException{return PalantirWorkflowRuntime.read(path,16777216);}
    static double scalar(Object value)throws IOException{return CellPhoneDbWorkflowData.numeric(value);}
    static Vector vector(Path home,Object value)throws IOException {
        var a=object(value);require(text(a.get("kind")).equals("binary-numeric-array"),"Primitive binary array required");String dtype=text(a.get("dtype"));int width=switch(dtype){case "<f8","<i8"->8;case "<i4"->4;case "|u1"->1;default->throw new IOException("Unsupported primitive array dtype");};var shape=new ArrayList<Integer>();long count=1;for(Object n:list(a.get("shape"))){int size=Math.toIntExact(integer(n,0,100000));shape.add(size);count=Math.multiplyExact(count,size);require(count<=25000000,"Complete original array capacity exceeded");}String name=NextflowFiles.member(text(a.get("path")));require(name.matches("objects/[0-9a-f]{64}\\.bin"),"Require bound data-only object member");Path path=home.resolve(name);var expected=NextflowFiles.fingerprint(a,200000000);byte[] raw=NextflowFiles.bytes(path,200000000);require(raw.length==count*width&&expected.equals(new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw))),"Complete original array source/shape/hash differs");return new Vector(List.copyOf(shape),dtype,ByteBuffer.wrap(raw).order(ByteOrder.LITTLE_ENDIAN),Math.toIntExact(count));
    }
    static double[][] matrix(Path home,Object raw)throws IOException {var value=object(raw);if("dataframe".equals(value.get("kind"))){int n=list(value.get("index")).size(),p=list(value.get("columns")).size();var columns=list(value.get("column_data"));require(columns.size()==p&&(long)n*p<=25000000,"Complete original numeric frame shape differs");double[][] result=new double[n][p];for(int j=0;j<p;j++){var v=vector(home,columns.get(j));require(v.shape().size()==1&&v.length()==n,"Complete numeric frame column differs");for(int i=0;i<n;i++)result[i][j]=v.get(i);}return result;}var v=vector(home,raw);require(v.shape().size()==2,"Complete rank-two matrix required");int n=v.shape().get(0),p=v.shape().get(1);double[][] out=new double[n][p];for(int i=0;i<n;i++)for(int j=0;j<p;j++)out[i][j]=v.get(i*p+j);return out;}
    static int[][] adjacency(Path home,Object raw)throws IOException {var v=vector(home,raw);require(v.shape().size()==2&&v.shape().get(0).equals(v.shape().get(1)),"Complete square adjacency required");int n=v.shape().get(0);int[][] result=new int[n][n];for(int i=0;i<n;i++)for(int j=0;j<n;j++){double d=v.get(i*n+j);require(d==0||d==1,"Original binary adjacency differs");result[i][j]=(int)d;}return result;}
    static void close(double actual,double expected,String context)throws IOException {
        numeric++;if(!Double.isFinite(expected)){nonfinite++;require(Double.isNaN(expected)?Double.isNaN(actual):actual==expected,"Original nonfinite state differs: "+context);return;}require(Double.isFinite(actual),"Introduced nonfinite state: "+context);if(expected==0){require(Double.doubleToRawLongBits(actual)==Double.doubleToRawLongBits(expected),"Original signed zero state differs: "+context);return;}require(actual!=0&&Math.abs(actual-expected)<=5e-12*Math.abs(expected)+16*Math.ulp(expected),"Original numeric value differs: "+context+" actual="+actual+" expected="+expected);
    }
    /** A correlation near one loses relative precision in 1-correlation. Keep this
     * explicitly scaled comparison separate from all matrix/assignment checks.
     * It is a declared software comparison envelope, not a universal error bound. */
    static boolean correlationScoreMatches(double actual,double expected,double absoluteEnvelope){return Double.isFinite(actual)&&Double.isFinite(expected)&&Math.abs(actual-expected)<=absoluteEnvelope+5e-12*Math.abs(expected)+16*Math.ulp(expected);}
    static void diagnostic(double actual,double expected,int term,double[][] r,int dimensions,String context)throws IOException {
        if(term!=0||!Double.isFinite(expected)){close(actual,expected,context+" term"+term);return;}
        double mass=0;for(double[] row:r)for(double v:row)mass+=Math.abs(v);
        double envelope=(8.0*dimensions+16)*Math.ulp(1.0)*mass/r.length;
        numeric++;require(correlationScoreMatches(actual,expected,envelope),"Original correlation score exceeds declared cancellation comparison: "+context+" actual="+actual+" expected="+expected+" envelope="+envelope);
        var report=new LinkedHashMap<String,Object>();report.put("context",context);report.put("actual",actual);report.put("original",expected);report.put("absolute_difference",Math.abs(actual-expected));report.put("correlation_cancellation_absolute_envelope",envelope);report.put("relative_envelope",5e-12);report.put("not_a_universal_roundoff_bound",true);diagnosticComparisons.add(report);
    }
    static void compare(Path home,Object expected,double[][] actual,String context)throws IOException {var v=vector(home,expected);require(v.shape().size()==2&&v.shape().get(0)==actual.length,"Complete matrix row family differs");int columns=v.shape().get(1);for(int i=0;i<actual.length;i++){require(actual[i].length==columns,"Complete matrix column family differs");for(int j=0;j<columns;j++)close(actual[i][j],v.get(i*columns+j),context+"["+i+","+j+"]");}}
    static double[][] transpose(double[][] value){double[][] result=new double[value[0].length][value.length];for(int i=0;i<value.length;i++)for(int j=0;j<value[i].length;j++)result[j][i]=value[i][j];return result;}
    static int rejections()throws Exception {
        int n=0;var outputRows=new SimplePptMath.Limits(1,3,9,1000);var tiny=new SimplePptMath.Limits(1,1,1,1);List<Runnable> failures=List.of(()->SimplePptMath.conditionalSystem(new int[3][3],new double[][]{{1,0,0}},1,outputRows),()->SimplePptMath.conditionalRightHandSide(new double[][]{{1,2}},null,new double[][]{{1,0,0}},outputRows),()->SimplePptMath.assignments(new double[][]{{-1}},1,LIMITS),()->SimplePptMath.assignments(new double[][]{{Double.NaN}},1,LIMITS),()->SimplePptMath.assignments(new double[][]{{Double.POSITIVE_INFINITY}},1,LIMITS),()->SimplePptMath.assignments(new double[][]{{0}},0,LIMITS),()->SimplePptMath.assignments(new double[][]{{0}},Double.NaN,LIMITS),()->SimplePptMath.assignments(new double[][]{{0},{0,1}},1,LIMITS),()->SimplePptMath.assignments(new double[][]{{0,1}},1,tiny),()->SimplePptMath.assignments(new double[][]{{0}},1,tiny),()->SimplePptMath.convergenceError(new double[][]{{1}},new double[][]{{1,2}},LIMITS),()->SimplePptMath.conditionalSystem(new int[][]{{0,1},{0,0}},new double[][]{{.5,.5}},1,LIMITS),()->SimplePptMath.conditionalRightHandSide(new double[][]{{1}},new double[][]{{Double.NaN}},new double[][]{{1}},LIMITS));
        for(Runnable f:failures){boolean rejected=false;try{f.run();}catch(IllegalArgumentException expected){rejected=true;}require(rejected,"Invalid native input unexpectedly returned a partial result");n++;}Thread.currentThread().interrupt();try{boolean rejected=false;try{SimplePptMath.assignments(new double[][]{{0}},1,LIMITS);}catch(java.util.concurrent.CancellationException expected){rejected=true;}require(rejected,"Interrupted native computation was not rejected");n++;}finally{Thread.interrupted();}
        double[][] input={{0,1}};var r=SimplePptMath.assignments(input,1,LIMITS);double original=r.weights()[0][0];r.weights()[0][0]=99;input[0][0]=99;require(r.weights()[0][0]==original&&r.kernel()[0][0]==1,"Assignment result did not retain defensive copies");double[][] nodes={{0,1}};var rhs=SimplePptMath.conditionalRightHandSide(nodes,null,new double[][]{{1}},LIMITS);rhs.values()[0][0]=99;require(rhs.values()[0][0]==0,"Conditional result did not retain defensive copies");return n;
    }
    public static void main(String[] args)throws Exception {
        require(args.length==2,"ORIGINAL_FAMILY NEW_REPORT");Path root=Path.of(args[0]).toAbsolutePath().normalize(),out=Path.of(args[1]).toAbsolutePath().normalize();require(!Files.exists(out,LinkOption.NOFOLLOW_LINKS),"New report only");var complete=read(root.resolve("COMPLETED.json"));require(text(complete.get("status")).equals("PASS_COMPLETE_ORIGINAL_SCFATES_CPU_ARITHMETIC_AND_WORKFLOWS_ONLY"),"Complete original reference family not admitted");require(list(complete.get("arithmetic_cases")).size()==40&&list(complete.get("workflows")).size()==12,"Incomplete original family");var caseIds=new HashSet<String>();var workflowIds=new HashSet<String>();var byMethod=new TreeMap<String,Integer>();long zeroRows=0,mapped=0;
        for(Object raw:list(complete.get("arithmetic_cases"))){var entry=object(raw);String id=text(entry.get("id")),method=text(entry.get("method"));require(id.matches("[A-Za-z0-9_.-]+")&&caseIds.add(id),"Unsafe/duplicate case identity");Path home=root.resolve(id);var c=read(home.resolve("CASE.json"));require(text(c.get("method")).equals(method)&&text(c.get("id")).equals(id),"Complete case family changed");
            switch(method){
                case "assignments" -> {var r=SimplePptMath.assignments(matrix(home,c.get("distances")),scalar(c.get("sigma")),LIMITS);compare(home,c.get("kernel"),r.kernel(),id+" kernel");compare(home,c.get("assignments"),r.weights(),id+" R");var expected=vector(home,c.get("row_sums"));require(expected.length()==r.rowSums().length,"Complete row sums differ");double[] sums=r.rowSums();for(int i=0;i<sums.length;i++)close(sums[i],expected.get(i),id+" row sum");require(r.zeroMassRows()==integer(c.get("source_zero_rows"),0,100000)&&r.sourceNaNsMappedToZero()==integer(c.get("source_nan_mapped_to_zero"),0,25000000),"Original underflow/NaN mapping dispositions differ");zeroRows+=r.zeroMassRows();mapped+=r.sourceNaNsMappedToZero();}
                case "convergence" -> close(SimplePptMath.convergenceError(matrix(home,c.get("previous_nodes")),matrix(home,c.get("new_nodes")),LIMITS),scalar(c.get("error")),id+" original signed-coordinate-sum error");
                case "conditional" -> {var x=matrix(home,c.get("points"));var f=matrix(home,c.get("nodes"));var r=matrix(home,c.get("assignments"));var b=adjacency(home,c.get("adjacency"));double sigma=scalar(c.get("sigma")),lambda=scalar(c.get("lam"));compare(home,c.get("system"),SimplePptMath.conditionalSystem(b,r,lambda,LIMITS).values(),id+" conditional M");compare(home,c.get("right_hand_side"),SimplePptMath.conditionalRightHandSide(x,c.get("weights")==null?null:matrix(home,c.get("weights")),r,LIMITS).values(),id+" conditional RHS");var scores=SimplePptMath.diagnostics(x,f,r,matrix(home,c.get("pre_update_distances")),b,sigma,lambda,LIMITS).terms();var expected=list(c.get("scores"));require(expected.size()==3,"Complete original diagnostic family differs");for(int i=0;i<3;i++)diagnostic(scores[i],scalar(expected.get(i)),i,r,x[0].length,id+" arithmetic score");}
                default -> throw new IOException("Unknown original arithmetic method");
            }cases++;byMethod.merge(method,1,Integer::sum);
        }
        long observedFits=0;for(Object raw:list(complete.get("workflows"))){var workflow=object(raw);String id=text(workflow.get("id"));require(id.matches("[A-Za-z0-9_.-]+")&&workflowIds.add(id),"Unsafe/duplicate workflow identity");Path home=root.resolve(id),path=home.resolve("observed-final-ppt-step.json");if(!Files.exists(path,LinkOption.NOFOLLOW_LINKS))continue;var local=object(read(path).get("locals"));var x=transpose(matrix(home,local.get("X_cpu")));var w=transpose(matrix(home,local.get("W")));var r=matrix(home,local.get("R"));var b=adjacency(home,local.get("B"));var previous=transpose(matrix(home,local.get("old_F")));var current=transpose(matrix(home,local.get("F_mat_cpu")));double sigma=scalar(local.get("sigma")),lambda=scalar(local.get("lam"));var system=SimplePptMath.conditionalSystem(b,r,lambda,LIMITS).values();compare(home,local.get("M"),system,id+" actual final-step M");close(SimplePptMath.convergenceError(previous,current,LIMITS),scalar(local.get("err")),id+" actual final-step convergence");var rhs=SimplePptMath.conditionalRightHandSide(x,w,r,LIMITS).values();require(rhs.length==current.length,"Conditional fitted-node family differs");for(int i=0;i<rhs.length;i++)for(int c=0;c<rhs[i].length;c++){double left=0,scale=Math.abs(rhs[i][c]);for(int j=0;j<rhs.length;j++)if(system[j][i]!=0){double term=system[j][i]*current[j][c];left+=term;scale+=Math.abs(term);}numeric++;require(Double.isFinite(left)&&Double.isFinite(rhs[i][c])&&Math.abs(left-rhs[i][c])<=1e-10*Math.max(Double.MIN_NORMAL,scale),"Original conditional fitted-node residual differs: "+id);}var d=matrix(home,local.get("d"));var score=SimplePptMath.diagnostics(x,current,r,d,b,sigma,lambda,LIMITS).terms();var expected=list(local.get("score"));for(int i=0;i<3;i++)diagnostic(score[i],scalar(expected.get(i)),i,r,x[0].length,id+" actual final-step score");observedFits++;}
        require(cases==40&&observedFits==10&&byMethod.equals(Map.of("assignments",30,"convergence",5,"conditional",5)),"Incomplete numeric or observed-fit method family");int rejected=rejections();require(!correlationScoreMatches(1e-9,0,1e-14)&&!correlationScoreMatches(-1e-9,0,1e-14)&&!correlationScoreMatches(Double.NaN,0,1e-14)&&!correlationScoreMatches(Double.POSITIVE_INFINITY,0,1e-14)&&!correlationScoreMatches(1e-6,1,1e-14),"Correlation comparison admitted a numerical corruption");var report=new LinkedHashMap<String,Object>();report.put("status","PASS_COMPLETE_ORIGINAL_SIMPLEPPT_CPU_ARITHMETIC_ONLY");report.put("cases",cases);report.put("actual_original_fit_observations",observedFits);report.put("numeric_states",numeric);report.put("nonfinite_states",nonfinite);report.put("source_zero_mass_rows",zeroRows);report.put("source_normalization_NaNs_mapped_to_zero",mapped);report.put("methods",byMethod);report.put("native_rejections",rejected);report.put("correlation_comparison_corruptions_rejected",5);report.put("correlation_cancellation_comparisons",diagnosticComparisons);report.put("complete_tree_fitter",false);report.put("implementation_credit",false);NextflowFiles.writeJson(out,report);
    }
}
